// HAND-OWNED (quick-log). Not generated by Bubblewrap. Pure helpers for SettingsActivity (P6).
package io.github.palo007.twa.quicklog

import java.util.Locale

/** One OEM "autostart" screen: package + activity class. */
internal data class OemComponent(val pkg: String, val cls: String)

/** DL-12: the "Allow unrestricted battery" button (API 23+ only, hidden when already unrestricted). */
internal fun showUnrestrictedBattery(sdk: Int, ignoring: Boolean): Boolean = sdk >= 23 && !ignoring

private val MIUI = listOf(
    OemComponent("com.miui.securitycenter", "com.miui.permcenter.autostart.AutoStartManagementActivity"),
    OemComponent("com.miui.securitycenter", "com.miui.powercenter.PowerSettings"),
)
private val HUAWEI = listOf(
    OemComponent("com.huawei.systemmanager", "com.huawei.systemmanager.startupmgr.ui.StartupNormalAppListActivity"),
    OemComponent("com.huawei.systemmanager", "com.huawei.systemmanager.optimize.process.ProtectActivity"),
)
private val OPPO = listOf(
    OemComponent("com.coloros.safecenter", "com.coloros.safecenter.permission.startup.StartupAppListActivity"),
    OemComponent("com.coloros.safecenter", "com.coloros.safecenter.startupapp.StartupAppListActivity"),
    OemComponent("com.oppo.safe", "com.oppo.safe.permission.startup.StartupAppListActivity"),
)
private val ONEPLUS = listOf(
    OemComponent("com.oneplus.security", "com.oneplus.security.chainlaunch.view.ChainLaunchAppListActivity"),
) + OPPO
private val VIVO = listOf(
    OemComponent("com.vivo.permissionmanager", "com.vivo.permissionmanager.activity.BgStartUpManagerActivity"),
    OemComponent("com.iqoo.secure", "com.iqoo.secure.ui.phoneoptimize.AddWhiteListActivity"),
)

/**
 * DL-12: known autostart screens for [manufacturer] (Build.MANUFACTURER), tried in order; empty =
 * hide the button. Names change between OEM versions, so the caller must catch and fall back.
 */
internal fun autostartComponents(manufacturer: String?): List<OemComponent> =
    when (manufacturer?.trim()?.lowercase(Locale.ROOT)) {
        "xiaomi", "redmi", "poco" -> MIUI
        "huawei", "honor" -> HUAWEI
        "oppo", "realme" -> OPPO
        "oneplus" -> ONEPLUS
        "vivo", "iqoo" -> VIVO
        else -> emptyList()
    }

/** P9 / P1d-m2 (TWA-A8): keep the "open Android Settings" hint across render() until exact alarms are allowed. */
internal fun showExactAlarmHint(requested: Boolean, exactAllowed: Boolean): Boolean = requested && !exactAllowed

/** P9 / P1d-m3: Toast after "Try again"; null when something moved (the status line shows it). */
internal fun retryToast(moved: Int): String? = if (moved <= 0) "Nothing to retry" else null

private const val STALE_DAYS = 7

/** DL-16: "never", "just now", "N min ago", "N h ago", "N days ago"; older than 7 days adds a hint. */
internal fun syncAgeLine(ms: Long, nowMs: Long): String {
    if (ms <= 0L) return "never"
    val age = nowMs - ms
    val minutes = age / 60_000L
    val hours = minutes / 60
    val days = hours / 24
    return when {
        minutes < 1 -> "just now"
        hours < 1 -> "$minutes min ago"
        days < 1 -> "$hours h ago"
        days == 1L -> "1 day ago"
        days > STALE_DAYS -> "$days days ago — open Questa to sync"
        else -> "$days days ago"
    }
}
